-- PostgreSQL schema foundation. Facts in demo_seed.sql are synthetic and never VERIFIED.
CREATE EXTENSION IF NOT EXISTS vector;
CREATE TABLE registry_snapshot (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), snapshot_date DATE NOT NULL, source_uri TEXT, source_hash TEXT, state TEXT NOT NULL CHECK (state IN ('VERIFIED','DEMO','UNKNOWN')), created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE app_user (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), display_name TEXT NOT NULL, email TEXT UNIQUE, role TEXT NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE audit (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), title TEXT NOT NULL, tender_id TEXT NOT NULL, organization TEXT NOT NULL, category TEXT NOT NULL, tender_date DATE NOT NULL, publication_date DATE, language TEXT NOT NULL DEFAULT 'English', state TEXT NOT NULL DEFAULT 'Draft', data_state TEXT NOT NULL DEFAULT 'DEMO', owner_id UUID REFERENCES app_user(id), registry_snapshot_id UUID REFERENCES registry_snapshot(id), created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE tender_document (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), audit_id UUID NOT NULL REFERENCES audit(id) ON DELETE CASCADE, filename TEXT NOT NULL, mime_type TEXT NOT NULL, sha256 TEXT, page_count INTEGER, ocr_provider TEXT, ocr_state TEXT NOT NULL DEFAULT 'UNKNOWN', language TEXT, storage_key TEXT NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE requirement (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), audit_id UUID NOT NULL REFERENCES audit(id) ON DELETE CASCADE, external_id TEXT NOT NULL, text TEXT NOT NULL, normalized_text TEXT, category TEXT NOT NULL, parameter TEXT, value TEXT, unit TEXT, operator TEXT, grade TEXT, rating TEXT, product TEXT, source_page INTEGER, source_section TEXT, source_text TEXT, confidence NUMERIC(4,3), state TEXT NOT NULL DEFAULT 'REQUIRES_REVIEW', embedding vector(1024), UNIQUE(audit_id, external_id));
CREATE TABLE requirement_evidence (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), requirement_id UUID NOT NULL REFERENCES requirement(id) ON DELETE CASCADE, document_id UUID REFERENCES tender_document(id), page INTEGER, section TEXT, excerpt_pointer TEXT, evidence_state TEXT NOT NULL DEFAULT 'DEMO');
CREATE TABLE standard (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), standard_number TEXT NOT NULL UNIQUE, title TEXT, registry_state TEXT NOT NULL DEFAULT 'UNKNOWN', official_source TEXT, snapshot_id UUID REFERENCES registry_snapshot(id));
CREATE TABLE standard_version (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), standard_id UUID NOT NULL REFERENCES standard(id) ON DELETE CASCADE, year INTEGER, effective_date DATE, withdrawal_date DATE, state TEXT NOT NULL DEFAULT 'UNKNOWN', source_reference TEXT);
CREATE TABLE amendment (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), standard_version_id UUID NOT NULL REFERENCES standard_version(id) ON DELETE CASCADE, amendment_number TEXT, effective_date DATE, state TEXT NOT NULL DEFAULT 'UNKNOWN', source_reference TEXT);
CREATE TABLE standard_relationship (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), standard_id UUID NOT NULL REFERENCES standard(id), related_standard_id UUID NOT NULL REFERENCES standard(id), relationship_type TEXT NOT NULL, evidence_state TEXT NOT NULL DEFAULT 'UNKNOWN');
CREATE TABLE certification_rule (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), product_category TEXT NOT NULL, scheme TEXT NOT NULL, applicability TEXT NOT NULL DEFAULT 'UNKNOWN', effective_date DATE, source_uri TEXT, evidence_state TEXT NOT NULL DEFAULT 'UNKNOWN');
CREATE TABLE qco_record (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), product_category TEXT NOT NULL, order_name TEXT, effective_date DATE, source_uri TEXT, applicability TEXT NOT NULL DEFAULT 'UNKNOWN', evidence_state TEXT NOT NULL DEFAULT 'UNKNOWN');
CREATE TABLE checklist (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), category TEXT NOT NULL, version TEXT NOT NULL, state TEXT NOT NULL DEFAULT 'DEMO', created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE checklist_item (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), checklist_id UUID NOT NULL REFERENCES checklist(id), decision_point TEXT NOT NULL, expected_field TEXT, mandatory BOOLEAN NOT NULL DEFAULT false, evidence_state TEXT NOT NULL DEFAULT 'DEMO');
CREATE TABLE standard_recommendation (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), requirement_id UUID NOT NULL REFERENCES requirement(id), standard_id UUID REFERENCES standard(id), confidence NUMERIC(4,3), keyword_score NUMERIC(4,3), semantic_score NUMERIC(4,3), reranker_score NUMERIC(4,3), explanation JSONB NOT NULL DEFAULT '{}', evidence_state TEXT NOT NULL DEFAULT 'DEMO', review_state TEXT NOT NULL DEFAULT 'REQUIRES_REVIEW');
CREATE TABLE decision_point (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), audit_id UUID NOT NULL REFERENCES audit(id), checklist_item_id UUID REFERENCES checklist_item(id), label TEXT NOT NULL, state TEXT NOT NULL DEFAULT 'UNKNOWN', evidence JSONB NOT NULL DEFAULT '{}');
CREATE TABLE requirement_decision_point (requirement_id UUID REFERENCES requirement(id), decision_point_id UUID REFERENCES decision_point(id), PRIMARY KEY(requirement_id, decision_point_id));
CREATE TABLE compliance_result (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), requirement_id UUID NOT NULL REFERENCES requirement(id), coverage_state TEXT NOT NULL, coverage_percent NUMERIC(5,2), risk TEXT, suggested_action TEXT, evidence JSONB NOT NULL DEFAULT '{}');
CREATE TABLE wording_flag (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), requirement_id UUID NOT NULL REFERENCES requirement(id), phrase TEXT NOT NULL, issue TEXT NOT NULL, proposed_text TEXT, state TEXT NOT NULL DEFAULT 'REQUIRES_REVIEW');
CREATE TABLE conflict (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), audit_id UUID NOT NULL REFERENCES audit(id), area TEXT NOT NULL, description TEXT NOT NULL, source_references JSONB NOT NULL DEFAULT '[]', state TEXT NOT NULL DEFAULT 'REQUIRES_REVIEW');
CREATE TABLE officer_review (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), recommendation_id UUID NOT NULL REFERENCES standard_recommendation(id), officer_id UUID REFERENCES app_user(id), decision TEXT NOT NULL, reason TEXT NOT NULL, before_value JSONB, after_value JSONB, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE improved_tender (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), audit_id UUID NOT NULL REFERENCES audit(id), requirement_id UUID REFERENCES requirement(id), original_text TEXT NOT NULL, proposed_text TEXT NOT NULL, state TEXT NOT NULL DEFAULT 'REQUIRES_REVIEW', approved_by UUID REFERENCES app_user(id), created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE audit_log (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), audit_id UUID NOT NULL REFERENCES audit(id), user_id UUID REFERENCES app_user(id), action TEXT NOT NULL, entity_type TEXT NOT NULL, entity_id TEXT, before_value JSONB, after_value JSONB, reason TEXT, source TEXT, confidence NUMERIC(4,3), created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE INDEX requirement_audit_idx ON requirement(audit_id);
CREATE INDEX audit_log_audit_time_idx ON audit_log(audit_id, created_at);
